import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class PedidoServiceTest {
    @Test
    void deveCalcularTotalComFrete() {
        FreteClient freteMock = mock(FreteClient.class);
        when(freteMock.calcular("01000")).thenReturn(15.0);

        var service = new PedidoService(freteMock);
        assertEquals(115.0, service.fecharPedido(100.0, "01000"));
        verify(freteMock).calcular("01000");
    }
}

